	@Test
	public void branchLocalBindInsideUnionPreservesNativeStoreResults() throws Exception {
		assertBranchLocalBindInsideUnionPreservesNativeStoreResults(true);
	}

	@Test
	public void loweredStartsWithRegexInsideUnionRemainsEligibleForScopeRemoval() throws Exception {
		assertBranchLocalBindInsideUnionPreservesNativeStoreResults(false);
	}

	private void assertBranchLocalBindInsideUnionPreservesNativeStoreResults(boolean caseInsensitive) throws Exception {
		try (RepositoryConnection connection = testRepository.getConnection()) {
			IRI leftSubject = vf.createIRI("urn:left-subject");
			IRI rightSubject = vf.createIRI("urn:right-subject");
			IRI leftPredicate = vf.createIRI("urn:left-predicate");
			IRI rightPredicate = vf.createIRI("urn:right-predicate");
			IRI seed = vf.createIRI("urn:seed");
			connection.add(leftSubject, leftPredicate, vf.createLiteral("needle left", "en"));
			connection.add(rightSubject, rightPredicate, vf.createLiteral("needle right", "en"));

			String regexArgs = caseInsensitive ? "'^needle', 'i'" : "'^needle'";
			String query = "SELECT ?seed ?s ?o ?label WHERE { VALUES ?seed { <urn:seed> } "
					+ "{ ?s <urn:left-predicate> ?o . FILTER(LANGMATCHES(LANG(?o), 'en')) "
					+ "FILTER(REGEX(STR(?o), " + regexArgs + ")) BIND(STR(?o) AS ?label) } "
					+ "UNION { ?s <urn:right-predicate> ?o . FILTER(LANGMATCHES(LANG(?o), 'en')) "
					+ "FILTER(REGEX(STR(?o), " + regexArgs + ")) BIND(STR(?o) AS ?label) } }";
			ParsedTupleQuery rawQuery = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, query, null);
			DefaultEvaluationStrategy rawStrategy = new DefaultEvaluationStrategy(
					new RepositoryTripleSource(connection),
					rawQuery.getDataset(), null);
			List<BindingSet> rawResults = new ArrayList<>();
			try (var result = rawStrategy.evaluate(rawQuery.getTupleExpr(), EmptyBindingSet.getInstance())) {
				while (result.hasNext()) {
					rawResults.add(result.next());
				}
			}

			ParsedTupleQuery optimizedQuery = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, query, null);
			DefaultEvaluationStrategy optimizedStrategy = new DefaultEvaluationStrategy(
					new RepositoryTripleSource(connection), optimizedQuery.getDataset(), null);
			TupleExpr optimizedExpr = optimizedQuery.getTupleExpr();
			optimizedStrategy.optimize(optimizedExpr, new EvaluationStatistics(), EmptyBindingSet.getInstance());
			List<BindingSet> optimizedResults = new ArrayList<>();
			try (var result = optimizedStrategy.evaluate(optimizedExpr, EmptyBindingSet.getInstance())) {
				while (result.hasNext()) {
					optimizedResults.add(result.next());
				}
			}

			assertThat(rawResults).hasSize(2);
			assertThat(optimizedResults).containsExactlyInAnyOrderElementsOf(rawResults);
			assertThat(rawResults).allSatisfy(row -> {
				assertThat(row.getValue("seed")).isEqualTo(seed);
				assertThat(row.getValue("label").stringValue()).startsWith("needle ");
			});

			List<Union> unions = new ArrayList<>();
			optimizedExpr.visit(new AbstractQueryModelVisitor<RuntimeException>() {
				@Override
				public void meet(Union union) {
					unions.add(union);
					super.meet(union);
				}
			});
			assertThat(unions).hasSize(1);
			if (caseInsensitive) {
				assertThat(optimizedExpr.toString()).contains("Regex");
			} else {
				assertThat(optimizedExpr.toString())
						.contains("FunctionCall (http://www.w3.org/2005/xpath-functions#starts-with)");
			}
			assertThat(unions.getFirst().isVariableScopeChange()).as(optimizedExpr.toString()).isFalse();
		}
	}

	@Override
	protected Repository createRepository() {
		return new SailRepository(new NativeStore(dataDir, "spoc"));
	}
